from pathlib import Path
import json,csv,re
D=Path(__file__).resolve().parent
items=[];talks=[];problems=[];corrections=[];bib={};audit=[]
def add(record,title,pages,kind,notes,statement,fate,refs=(),cl='E',literal='correct with missing hypotheses',match='partial',verification='publisher metadata checked',reconstruction='',status='',confidence='high',problem='',worth='',speaker=None,development='annotated'):
    n=1+sum(x['record']==record for x in items)
    x=dict(id=f'1982-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cl},fate=fate,present_status='As of November 2026: '+(status or ('the qualified statement is established; the notebook is an exposition, not a newly open question.' if cl=='E' else 'the identification and limits are as stated above.')),literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker:x['speaker']=speaker
    items.append(x)
    return x['id']
def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def corr(page,place,reads,should,evidence,type='faithful_error',applies='both'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=type))
def ref(key,author,title,year,url,**fields):
    typ=fields.pop('type','article'); data=dict(author=author,title=title,year=str(year),**fields,url=url,note='verified')
    bib[key]='@'+typ+'{'+key+',\n'+''.join('  '+k+' = {'+str(v)+'},\n' for k,v in data.items())+'}\n'
def cumulative(key,annotation):
    s=(D.parents[1]/'references_cumulative.bib').read_text()
    es=[x for x in re.split(r'(?=^@)',s,flags=re.M) if re.match(r'@\w+\{'+re.escape(key)+r',',x)]
    assert es,key
    e=es[-1]
    e=re.sub(r'\n\s*(?:annote|verificationrecord)\s*=\s*\{[^\n]*\},?', '',e)
    e=re.sub(r'note\s*=\s*\{(?:unverified|verified)\}',r'note = {verified}',e)
    pos=e.rfind('}');e=e[:pos].rstrip().rstrip(',')+',\n  annote = {'+annotation+'}\n'+e[pos:]
    bib[key]=e

def save():
    for name,obj in [('talks',talks),('items',items),('problems',problems)]: (D/f'{name}.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
    with (D/'corrections.csv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)
    (D/'references.bib').write_text('\n'.join(bib.values()).replace(r"{\cprime}", "'"))
    (D/'research_notes.md').write_text('# Records 561–573 research log\n\n'+'\n\n'.join(audit)+'\n')
    print(f'Saved {len(talks)} records, {len(items)} items, {len(problems)} problems, {len(corrections)} corrections, {len(bib)} references')

